ui.debug.addRules("cornerch",[{rules:"Shade some cells on the board to form regions of unshaded cells.\n1. A number indicates the size of the region that contains it.\n2. Clues represent the number of cells in the region they belong to. A region can contain one or more identical numbers, or none at all.\n3. If the number of cells in an unshaded group is even, the area must be rectangular. If the number of cells is odd, the area must not be rectangular.\n4. All unshaded areas must be connected diagonally.",history:"This genre first appeared in Puzzle Communication Nikoli vol. 191."},{rules:"1. 盤面のいくつかのマスを黒くぬりまし ょう。\n2. 盤面の数字は、その数字が含まれる、 黒マスによって分断されたところ (シマ と呼びます)のマスの数を表します。\n3. 1つのシマに、いくつ数字が入っても かまいません。また、数字が入っている マスを黒くぬってはいけません。\n4. マスの数が偶数のシマは必ず長方形 (正方形も含みます)になります。また、 マスの数が奇数のシマは必ず長方形 (正 方形も含みます) 以外の形になります。\n5. すべてのシマは頂点を通じてひとつな がりになっていなければなりません。",history:"パズル通信ニコリ vol.191より"}]),ui.debug.addDebugData("cornerch",{url:"6/6/g4j2s3g3h4i3l",failcheck:[["cuNotRect","pzprv3/cornerch/6/6/. 4 . . . . /2 . . . . . /. . . . . . /. . 3 . 3 . /. 4 . . . 3 /. . . . . . /# . . . . # /. # # # # . /. # . . # . /# # . # . # /# . # # . . /# . . . # # /"],["cuRect","pzprv3/cornerch/6/6/. 4 . . . . /2 . . . . . /. . . . . . /. . 3 . 3 . /. 4 . . . 3 /. . . . . . /# . . . . # /. # # # # . /. # # # # . /# # . . . # /. . # # # . /. . # # . . /"],["bkSizeNe","pzprv3/cornerch/6/6/. 4 . . . . /2 . . . . . /. . . . . . /. . 3 . 3 . /. 4 . . . 3 /. . . . . . /# . . . . # /. # # # # . /. # . . # . /# # . # . # /. . # # . . /. # . . # # /"],["csDivide8","pzprv3/cornerch/6/6/. 4 . . . . /2 . . . . . /. . . . . . /. . 3 . 3 . /. 4 . . . 3 /. . . . . . /# . . . . # /. # # # # # /. # . . # # /# # . # . . /. . # # # . /. . # # # # /"],[null,"pzprv3/cornerch/6/6/. 4 . . . . /2 . . . . . /. . . . . . /. . 3 . 3 . /. 4 . . . 3 /. . . . . . /# + + + + # /+ # # # # + /+ # + + # + /# # + # + # /+ + # # + + /+ + # # # # /"]],inputs:[]});
